parts.code:
// Coal (thermal) power station showpiece, hand-made. Units: cm, about real size (the distances between buildings are
// shortened). Coal comes from the west (−X), the turbine's axis runs along X, the power leaves to the east (+X); the chimney
// and the cooling tower stand behind (−Z). Outdoors: it has a sky and a 24-hour day (W.day). Helpers for later parts: W.store.
const S = W.store;
S.matte = (c, r = 0.92) => new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: 0 });
S.concrete = S.matte('#bdb7ab');
S.dark = S.matte('#4a4f55', 0.8);
S.lamps = []; // { m, k }: they light at dusk (W.env.dark)
S.turn = [];  // { o, axis, k }: turn with the machines
S.beam = (a, b, r, mat, seg = 6) => { // a round member from a to b
  const A = new THREE.Vector3(a[0], a[1], a[2]), B = new THREE.Vector3(b[0], b[1], b[2]);
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, A.distanceTo(B), seg), mat);
  m.position.copy(A).add(B).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), B.clone().sub(A).normalize());
  return m;
};
S.axisLathe = (profile, seg = 48, phiStart = 0, phiLen = Math.PI * 2) => { // around the X axis: [r, x] points
  const g = new THREE.LatheGeometry(profile.map((p) => new THREE.Vector2(Math.max(0.001, p[0]), p[1])), seg, phiStart, phiLen);
  g.rotateZ(-Math.PI / 2);
  return g;
};
S.wall = (cols, rows, o = {}) => { // a wall's sheeting with rows of windows; at night the windows glow
  const base = W.canvasTex(256, 128), glow = W.canvasTex(256, 128);
  const g = base.ctx, e = glow.ctx;
  g.fillStyle = o.wall || '#d3d6d9'; g.fillRect(0, 0, 256, 128);
  for (let x = 0; x < 256; x += 8) { g.fillStyle = 'rgba(0,0,0,0.06)'; g.fillRect(x, 0, 3, 128); } // (the sheets' ribs)
  e.fillStyle = '#000'; e.fillRect(0, 0, 256, 128);
  const cw = 256 / cols, rh = 128 / rows;
  for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) {
    const x = c * cw + cw * 0.16, y = r * rh + rh * (o.top || 0.22), w = cw * 0.68, h = rh * (o.h || 0.4);
    g.fillStyle = o.glass || '#33495c'; g.fillRect(x, y, w, h);
    e.fillStyle = (r * 7 + c * 3) % 5 === 0 ? '#3a2a10' : '#ffd9a0'; e.fillRect(x, y, w, h);
  }
  base.update(); glow.update();
  for (const t of [base.texture, glow.texture]) { t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(o.rx || 1, o.ry || 1); }
  const m = new THREE.MeshStandardMaterial({ map: base.texture, emissiveMap: glow.texture, emissive: new THREE.Color('#ffc977'), emissiveIntensity: 0, roughness: 0.6, metalness: 0.2 });
  S.lamps.push({ m, k: o.lit == null ? 0.9 : o.lit });
  return m;
};
S.lamp = (c = '#ffe2a8', k = 2.4) => { const m = W.glow(c, 0); S.lamps.push({ m, k }); return m; };

W.day({ start: 12, ground: '#6d7452', zoom: 0.8 });
const site = W.group();
site.add(W.mesh(W.box(39000, 20, 21000), S.matte('#a39d8f', 0.96), { at: [0, -9, -2200] })); // the plant's levelled ground
const asphalt = S.matte('#4f5357', 0.9);
for (const [x, z, w, d] of [[0, 5200, 39000, 700], [-1500, 1900, 600, 6000], [7000, -1500, 600, 8000], [-9000, 1500, 500, 7000], [3000, -4200, 14000, 500]]) {
  site.add(W.mesh(W.box(w, 6, d), asphalt, { at: [x, 4, z] }));
}
const pole = W.metal('#8d939a', { rough: 0.5 }), head = S.lamp('#ffe7b0', 3);
for (let x = -18000; x <= 18000; x += 3000) { // street lights along the main road
  site.add(W.mesh(W.cyl(10, 14, 900, 8), pole, { at: [x, 450, 4750] }));
  site.add(W.mesh(W.box(120, 14, 40), pole, { at: [x + 50, 895, 4750] }));
  site.add(W.mesh(W.box(70, 8, 30), head, { at: [x + 90, 886, 4750] }));
}
site.add(W.text('JARVIS · 500 MW థర్మల్ విద్యుత్ కేంద్రం', { size: 150, at: [-4000, 380, 5650], color: '#eef2f5', bg: '#2f5f8a' }));
for (const x of [-6600, -1400]) site.add(W.mesh(W.cyl(14, 14, 300, 8), pole, { at: [x, 150, 5640] }));
W.add(site, { label: 'ప్లాంట్ స్థలం', ground: true });
// the green belt: trees round the edge (a third of a plant's land is kept green)
const trees = W.group();
const crowns = new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1, 1), S.matte('#3f6b35', 0.95), 46);
const trunks = new THREE.InstancedMesh(new THREE.CylinderGeometry(1, 1.3, 1, 6), S.matte('#5a4632'), 46);
const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), P = new THREE.Vector3(), Z = new THREE.Vector3();
for (let i = 0; i < 46; i++) {
  const side = i % 3, u = (i * 0.618) % 1;
  const x = side === 0 ? -19000 + u * 38000 : side === 1 ? -19200 + (i % 2) * 600 : 19400 - (i % 2) * 500;
  const z0 = side === 0 ? 7200 + (i % 2) * 500 : -12000 + u * 18000, z = side === 2 && Math.abs(z0) < 1600 ? z0 + 3200 : z0;
  const s = 380 + ((i * 37) % 7) * 40;
  M.compose(P.set(x, 260 + s * 0.7, z), Q, Z.set(s, s * 1.15, s)); crowns.setMatrixAt(i, M);
  M.compose(P.set(x, 200, z), Q, Z.set(30, 400, 30)); trunks.setMatrixAt(i, M);
}
trees.add(crowns, trunks);
W.add(trees, { label: 'గ్రీన్ బెల్ట్ చెట్లు', ground: true });

const S = W.store;
const deg = (d) => d * 180 / Math.PI;
const yard = W.group();
const coalM = S.matte('#202022', 0.98);
const pile = (x, z, L, Wd, H) => { // a long stockpile: a stretched half-dome
  const m = new THREE.Mesh(new THREE.SphereGeometry(1, 40, 14, 0, Math.PI * 2, 0, Math.PI / 2), coalM);
  m.scale.set(L / 2, H, Wd / 2); m.position.set(x, 0, z);
  return m;
};
yard.add(pile(-15000, -1500, 5600, 2000, 900), pile(-15000, 2500, 5600, 2000, 820), pile(-17800, 500, 1400, 1200, 500));
W.add(yard, { label: 'బొగ్గు కుప్పలు', heat: [32, 38] });
// the stacker-reclaimer between the piles: a boom with a turning bucket wheel, on rails
const sr = W.group();
const yellow = W.paint('#e2b52a', { metallic: 0.2, rough: 0.45 });
sr.add(W.mesh(W.box(900, 260, 600), yellow, { at: [-14200, 330, 500] }));
sr.add(W.mesh(W.box(700, 500, 500), yellow, { at: [-14200, 700, 500] }));
const boom = S.beam([-14200, 900, 500], [-16600, 650, 1300], 70, yellow, 8);
sr.add(boom);
const wheelBase = W.group({ at: [-16700, 640, 1350], rot: [0, 30, 0] }), wheel = W.group();
wheelBase.add(wheel);
wheel.add(W.mesh(W.cyl(330, 330, 90, 24), W.metal('#7d6a3a', { rough: 0.5 }), { rot: [0, 0, 90] }));
for (let i = 0; i < 10; i++) {
  const a = (i / 10) * Math.PI * 2;
  wheel.add(W.mesh(W.box(110, 90, 130), W.metal('#4e4a44', { rough: 0.6 }), { at: [0, Math.sin(a) * 340, Math.cos(a) * 340], rot: [deg(a), 0, 0] }));
}
sr.add(wheelBase);
S.turn.push({ o: wheel, axis: 'x', k: 0.4, by: 'run', conv: true });
for (const z of [200, 800]) sr.add(W.mesh(W.box(6000, 16, 18), W.metal('#7a7f86'), { at: [-15000, 9, z] })); // its rails
W.add(sr, { label: 'స్టాకర్ రీక్లెయిమర్' });
// the train of open wagons on the siding
const train = W.group();
const rail = W.metal('#8a8f96', { rough: 0.4 });
for (const z of [6880, 7120]) train.add(W.mesh(W.box(11000, 16, 10), rail, { at: [-13800, 18, z] }));
const sleepers = new THREE.InstancedMesh(W.box(28, 12, 340), S.matte('#6b6156'), 160);
for (let i = 0; i < 160; i++) sleepers.setMatrixAt(i, new THREE.Matrix4().makeTranslation(-19200 + i * 68, 6, 7000));
train.add(sleepers);
const wagonM = W.paint('#5c3b2c', { metallic: 0.3, rough: 0.6 }), wheelM = W.metal('#3a3c40');
for (let i = 0; i < 9; i++) {
  const x = -17800 + i * 1080;
  train.add(W.mesh(W.box(1000, 280, 300), wagonM, { at: [x, 230, 7000] }));
  train.add(W.mesh(W.box(980, 40, 280), coalM, { at: [x, 380, 7000] }));
  for (const dx of [-330, 330]) for (const dz of [-115, 115]) train.add(W.mesh(W.cyl(45, 45, 20, 12), wheelM, { at: [x + dx, 60, 7000 + dz], rot: [90, 0, 0] }));
}
const loco = W.group();
loco.add(W.mesh(W.box(1700, 380, 310, 30), W.paint('#2f5a8a', { metallic: 0.3, rough: 0.4 }), { at: [-7900, 290, 7000] }));
loco.add(W.mesh(W.box(300, 120, 300), W.paint('#e8e2d0'), { at: [-7200, 420, 7000] }));
train.add(loco);
W.add(train, { label: 'బొగ్గు రైలు' });
// the main conveyor: from the transfer tower, up in an open gallery to the bunkers over the boiler's front
const cv = W.group();
const truss = W.metal('#9aa3ab', { rough: 0.5 });
cv.add(W.mesh(W.box(900, 1700, 900), S.matte('#9fa6ad', 0.7), { at: [-11000, 850, 500] })); // the transfer tower
cv.add(W.mesh(W.box(5600, 14, 140), W.rubber('#1d1e20'), { at: [-14200, 120, 500] })); // the yard belt
S.cvA = [-10600, 1650, 600]; S.cvB = [-6300, 4350, 2650];
const A = new THREE.Vector3(...S.cvA), B = new THREE.Vector3(...S.cvB), D = B.clone().sub(A), L = D.length();
const gal = W.group();
gal.position.copy(A).add(B).multiplyScalar(0.5);
gal.quaternion.setFromUnitVectors(new THREE.Vector3(1, 0, 0), D.clone().normalize());
gal.add(W.mesh(W.box(L, 20, 260), W.rubber('#1b1c1e'), { at: [0, -40, 0] }));
gal.add(W.mesh(W.box(L, 14, 300), truss, { at: [0, -70, 0] }));
for (const z of [-170, 170]) {
  gal.add(W.mesh(W.box(L, 14, 14), truss, { at: [0, 150, z] }), W.mesh(W.box(L, 14, 14), truss, { at: [0, -70, z] }));
  for (let x = -L / 2; x <= L / 2; x += 300) gal.add(W.mesh(W.box(12, 220, 12), truss, { at: [x, 40, z] }));
}
for (let x = -L / 2; x <= L / 2; x += 600) gal.add(W.mesh(W.box(14, 14, 340), truss, { at: [x, 150, 0] }));
gal.add(W.mesh(W.box(L, 8, 380), W.metal('#b9c0c6', { rough: 0.4 }), { at: [0, 170, 0] })); // its rain roof
cv.add(gal);
for (let k = 0.18; k < 0.95; k += 0.2) { // trestles under it
  const p = A.clone().lerp(B, k);
  cv.add(W.mesh(W.box(60, p.y - 80, 60), truss, { at: [p.x, (p.y - 80) / 2, p.z - 140] }), W.mesh(W.box(60, p.y - 80, 60), truss, { at: [p.x, (p.y - 80) / 2, p.z + 140] }));
}
W.add(cv, { label: 'కన్వేయర్ బెల్ట్', heat: [32, 40] });

const S = W.store;
// the boiler: a steel frame 60 m tall; inside, the furnace (its walls are water tubes), the fireball, the steam drum on top
const bx = -4000, bz = 0;
const frame = W.group();
const steel = W.paint('#5d6b78', { metallic: 0.4, rough: 0.55 });
for (let i = 0; i < 5; i++) for (let j = 0; j < 5; j++) {
  if (i > 0 && i < 4 && j > 0 && j < 4) continue;
  frame.add(W.mesh(W.box(70, 6000, 70), steel, { at: [bx - 2000 + i * 1000, 3000, bz - 2000 + j * 1000] }));
}
for (let y = 1000; y <= 6000; y += 1000) for (const s of [-1, 1]) {
  frame.add(W.mesh(W.box(4000, 50, 50), steel, { at: [bx, y, bz + s * 2000] }), W.mesh(W.box(50, 50, 4000), steel, { at: [bx + s * 2000, y, bz] }));
}
W.add(frame, { label: 'బాయిలర్ స్టీల్ ఫ్రేమ్', layer: 3 });
const boil = W.group();
const tubes = W.canvasTex(256, 64);
{ const g = tubes.ctx; for (let x = 0; x < 256; x += 8) { const gr = g.createLinearGradient(x, 0, x + 8, 0); gr.addColorStop(0, '#3a3e44'); gr.addColorStop(0.5, '#8d949c'); gr.addColorStop(1, '#3a3e44'); g.fillStyle = gr; g.fillRect(x, 0, 8, 64); } tubes.update(); tubes.texture.wrapS = THREE.RepeatWrapping; tubes.texture.repeat.set(10, 1); }
const wallM = new THREE.MeshStandardMaterial({ map: tubes.texture, roughness: 0.55, metalness: 0.6, side: THREE.DoubleSide });
const fx = bx - 700, fw = 1800, fh = 4600, fy = 600;
for (const [x, z, w, d] of [[fx, bz - fw / 2, fw, 30], [fx - fw / 2, bz, 30, fw], [fx + fw / 2, bz, 30, fw]]) boil.add(W.mesh(W.box(w, fh, d), wallM, { at: [x, fy + fh / 2, z] }));
boil.add(W.mesh(W.box(fw, 40, fw), wallM, { at: [fx, fy + fh, bz] })); // (the front wall is left off: the fire shows)
boil.add(W.mesh(new THREE.ConeGeometry(fw * 0.7, 500, 4, 1, true), wallM, { at: [fx, fy - 200, bz], rot: [180, 45, 0] })); // the ash hopper
S.flames = [];
const flameM = new THREE.MeshStandardMaterial({ color: 0x1a0a04, emissive: 0xff7a1e, emissiveIntensity: 0, transparent: true, opacity: 0.85, depthWrite: false });
const coreM = new THREE.MeshStandardMaterial({ color: 0x1a0a04, emissive: 0xffd36a, emissiveIntensity: 0, transparent: true, opacity: 0.9, depthWrite: false });
for (const [y, r, m] of [[1500, 520, flameM], [2100, 640, flameM], [2700, 560, flameM], [2050, 330, coreM], [3300, 420, flameM]]) {
  const f = W.mesh(W.sphere(r, 20), m, { at: [fx, y, bz] }); f.castShadow = false; boil.add(f); S.flames.push(f);
}
for (const [x, z] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) for (const y of [1500, 1900, 2300]) { // the burners at the four corners
  boil.add(W.mesh(W.cyl(45, 45, 140, 10), W.metal('#6a6f75'), { at: [fx + x * (fw / 2 - 20), y, bz + z * (fw / 2 - 20)], rot: [90, 45 * x * z, 0] }));
}
boil.add(W.mesh(W.box(1300, 3600, 1300), new THREE.MeshStandardMaterial({ map: tubes.texture, roughness: 0.6, metalness: 0.5 }), { at: [bx + 900, 3700, bz] })); // the back pass
for (let i = 0; i < 9; i++) boil.add(W.mesh(W.box(40, 900, 1500), W.metal('#9b6a52', { rough: 0.45 }), { at: [fx - 600 + i * 150, fy + fh - 650, bz] })); // superheater panels
W.add(boil, { label: 'బాయిలర్', heat: [40, 1250], layer: 3 });
const drum = W.group();
drum.add(W.mesh(W.cyl(110, 110, 2000, 32), W.paint('#8a3b30', { metallic: 0.4, rough: 0.5 }), { at: [bx, 5650, bz], rot: [90, 0, 0] }));
for (const z of [-1000, 1000]) drum.add(W.mesh(W.sphere(110, 24), W.paint('#8a3b30', { metallic: 0.4, rough: 0.5 }), { at: [bx, 5650, bz + z] }));
for (const z of [-700, 0, 700]) drum.add(W.mesh(W.cyl(14, 14, 160, 10), W.metal('#d0d3d6'), { at: [bx, 5800, bz + z] })); // safety valves
W.add(drum, { label: 'స్టీమ్ డ్రమ్', heat: [40, 360], layer: 3 });
// the cladding round it all: lifts away to show the boiler (🧅)
const clad = W.group();
const sheet = S.wall(10, 2, { wall: '#c4ccd4', glass: '#9aa7b2', top: 0.1, h: 0.08, lit: 0.25, rx: 2, ry: 3 });
for (const [x, z, w, d] of [[bx, bz - 2050, 4100, 30], [bx, bz + 2050, 4100, 30], [bx - 2050, bz, 30, 4100], [bx + 2050, bz, 30, 4100]]) clad.add(W.mesh(W.box(w, 6100, d), sheet, { at: [x, 3050, z] }));
clad.add(W.mesh(W.box(4200, 60, 4200), W.paint('#8d98a3', { metallic: 0.3, rough: 0.6 }), { at: [bx, 6120, bz] }));
clad.add(W.mesh(W.box(4120, 500, 4120), W.paint('#2f6fa8', { metallic: 0.3, rough: 0.5 }), { at: [bx, 5800, bz] })); // the blue band at the top
W.add(clad, { label: 'బాయిలర్ గోడలు', layer: 1, peelBy: [0, 7600, 0], explode: [0, 7600, 0] });
clad.traverse((x) => { if (x.isMesh) x.castShadow = false; });
// in front: the bunkers that hold the coal, the mills that grind it to powder, the pipes that blow it to the burners
const bay = W.group();
const bunM = W.paint('#77818b', { metallic: 0.4, rough: 0.55 });
bay.add(W.mesh(W.box(4200, 400, 900), W.paint('#9aa3ab', { metallic: 0.3, rough: 0.6 }), { at: [bx, 4450, 2700] })); // the tripper gallery
for (let i = 0; i < 5; i++) {
  const x = bx - 1600 + i * 800;
  bay.add(W.mesh(W.cyl(330, 330, 1100, 20), bunM, { at: [x, 3700, 2700] }));
  bay.add(W.mesh(W.cone(330, 500, 20), bunM, { at: [x, 2900, 2700], rot: [180, 0, 0] }));
  for (const dx of [-300, 300]) bay.add(W.mesh(W.box(40, 2700, 40), W.paint('#5d6b78'), { at: [x + dx, 1350, 2400] }));
}
W.add(bay, { label: 'బొగ్గు బంకర్లు', heat: [32, 40] });
const mills = W.group();
const millM = W.paint('#3e6e5a', { metallic: 0.35, rough: 0.5 });
for (let i = 0; i < 5; i++) {
  const x = bx - 1600 + i * 800;
  mills.add(W.mesh(W.cyl(240, 280, 520, 24), millM, { at: [x, 260, 2900] }));
  mills.add(W.mesh(W.cone(240, 260, 24), millM, { at: [x, 650, 2900] }));
  const top = W.group({ at: [x, 820, 2900] });
  top.add(W.mesh(W.cyl(90, 90, 80, 16), W.metal('#b0b5ba'), {}));
  for (let k = 0; k < 4; k++) top.add(W.mesh(W.box(150, 30, 20), W.metal('#7a7f86'), { rot: [0, k * 45, 0] }));
  mills.add(top);
  S.turn.push({ o: top, axis: 'y', k: 0.9, by: 'run' });
  mills.add(W.mesh(W.box(240, 200, 200), W.paint('#2f4f7a'), { at: [x, 120, 3300] })); // its motor
  mills.add(W.mesh(W.tube([[x, 700, 2850], [x, 1300, 2500], [x - 150, 1900, 1500], [bx - 700 + (i - 2) * 300, 1700 + (i % 3) * 300, 950]], 40, 24), W.metal('#8b8f94', { rough: 0.5 })));
}
W.add(mills, { label: 'బొగ్గు మిల్లులు', heat: [45, 95] });

const S = W.store;
const esp = W.group();
const espM = W.paint('#8f9aa4', { metallic: 0.35, rough: 0.6 });
for (const x of [-5000, -3000]) {
  esp.add(W.mesh(W.box(1800, 2200, 2800), espM, { at: [x, 2300, -4300] }));
  for (const z of [-5200, -4300, -3400]) esp.add(W.mesh(W.cone(500, 700, 4), W.paint('#6f7a84'), { at: [x, 850, z], rot: [180, 45, 0] }));
  for (const dx of [-800, 800]) for (const dz of [-1300, 1300]) esp.add(W.mesh(W.box(60, 1200, 60), W.paint('#5d6b78'), { at: [x + dx, 600, -4300 + dz] }));
  esp.add(W.mesh(W.box(1900, 100, 2900), W.paint('#6b7681'), { at: [x, 3450, -4300] }));
}
esp.add(W.mesh(W.box(3800, 900, 600), espM, { at: [-4000, 4300, -2500] })); // the duct from the boiler
esp.add(W.mesh(W.box(600, 2400, 600), espM, { at: [-4000, 3300, -2600] }));
W.add(esp, { label: 'ESP ఫిల్టర్', heat: [60, 145] });
const idf = W.group();
for (const x of [-4800, -3200]) {
  idf.add(W.mesh(W.cyl(300, 300, 280, 28), W.paint('#4b6f8f', { metallic: 0.3, rough: 0.5 }), { at: [x, 350, -6500], rot: [0, 0, 90] }));
  idf.add(W.mesh(W.box(500, 260, 300), W.paint('#2f4f7a'), { at: [x + 500, 150, -6500] }));
  const cp = W.group({ at: [x + 220, 300, -6500] });
  cp.add(W.mesh(W.cyl(60, 60, 60, 12), W.metal('#c0c4c8'), { rot: [0, 0, 90] }));
  for (let k = 0; k < 6; k++) cp.add(W.mesh(W.box(20, 20, 20), W.metal('#6a6f75'), { at: [0, Math.sin(k) * 45, Math.cos(k) * 45] }));
  idf.add(cp);
  S.turn.push({ o: cp, axis: 'x', k: 2.5, by: 'run' });
  idf.add(W.mesh(W.box(500, 500, 1400), W.paint('#8f9aa4', { metallic: 0.35, rough: 0.6 }), { at: [x, 350, -5700] }));
}
idf.add(W.mesh(W.box(2200, 600, 600), W.paint('#8f9aa4', { metallic: 0.35, rough: 0.6 }), { at: [-4000, 350, -7300] }));
W.add(idf, { label: 'ID ఫ్యాన్లు', heat: [45, 140] });
const ch = W.group();
const prof = [];
