// Inside the steam turbine, its casings taken off: one long shaft with rings of blades. Hot steam (red) enters the small
// HP blades, goes on to the IP, then splits both ways through the big LP blades and leaves cool (blue) for the condenser.
// Between the turning rings sit rings that do not turn (grey): they point the steam onto the next ring.
const Mx = new THREE.Matrix4(), Rx = new THREE.Matrix4();
const ring = (grp, x, r0, len, n, w, mat, twist) => { // n blades round the shaft at x, from radius r0 out by len, each turned by twist
  const m = new THREE.InstancedMesh(new THREE.BoxGeometry(w * 0.18, len, w), mat, n);
  const up = new THREE.Matrix4().makeTranslation(0, r0 + len / 2, 0), tw = new THREE.Matrix4().makeRotationY(twist), at = new THREE.Matrix4().makeTranslation(x, 0, 0);
  for (let i = 0; i < n; i++) m.setMatrixAt(i, Mx.copy(at).multiply(Rx.makeRotationX((i / n) * Math.PI * 2)).multiply(up).multiply(tw));
  grp.add(m);
  return m;
};
